<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { Head, Link, router, useForm, usePage, useRemember } from '@inertiajs/vue3';
import { ArrowUpRight, ChartColumn, Check, ChevronLeft, ChevronRight, CircleHelp, Download, FileStack, FileText, FolderOpen, History, Info, LayoutGrid, List, Loader2, Pencil, Search, SlidersHorizontal, Upload, X } from 'lucide-vue-next';
import MainLayout from '@/Layouts/MainLayout.vue';
import ResolutionPreview from '@/Components/Resolutions/ResolutionPreview.vue';
import { openResolutionUploads } from '@/Composables/useResolutionUploads';
import ResolutionDashboard from '@/Components/Resolutions/ResolutionDashboard.vue';
import ResolutionFolders from '@/Components/Resolutions/ResolutionFolders.vue';
import ResolutionSkeleton from '@/Components/Resolutions/ResolutionSkeleton.vue';

const props = defineProps({ records: Object, filters: Object, summary: Object, coverage: Object, expectedYearTotals: { type: Object, default: () => ({}) }, years: Array, yearCounts: { type: Array, default: () => [] }, folders: { type: Array, default: () => [] }, currentFolder: Object, annualBySeries: { type: Array, default: () => [] }, seriesOptions: Array, maxUploadMb: Number, currentYear: Number, access: { type: Object, default: () => ({ ver: false, subir: false, editar: false }) } });
const page = usePage();
const showDashboard = computed(() => !props.currentFolder && !['q', 'number', 'year', 'series', 'folder'].some(key => props.filters?.[key]) && (!props.filters?.status || props.filters.status === 'all'));
const defaults = { q: '', number: '', year: '', series: '', folder: '', status: 'all', sort: 'recent' };
const search = ref({ ...defaults, ...props.filters });
const searching = ref(false), advanced = ref(false), help = ref(false);
const pageLoading = ref(false), loadingView = ref('files');
let loadingVisit = null;
const stopLoadingStart = router.on('start', ({ detail: { visit } }) => {
    const url = new URL(visit.url, window.location.origin);
    if (visit.method !== 'get' || url.pathname !== '/resoluciones' || visit.only?.length) return;
    loadingVisit = visit;
    const filtered = ['q','number','year','series','folder'].some(key => url.searchParams.get(key)) || (url.searchParams.has('status') && url.searchParams.get('status') !== 'all');
    loadingView.value = filtered ? 'files' : homeView.value;
    pageLoading.value = true;
});
const stopLoadingNavigate = router.on('navigate', () => { pageLoading.value = false; loadingVisit = null; });
const stopLoadingFinish = router.on('finish', ({ detail: { visit } }) => {
    if (visit === loadingVisit) { pageLoading.value = false; loadingVisit = null; }
});
const notice = ref(''), editing = ref(null), preview = ref(null), searchInput = ref(null), resultsList = ref(null);
const showHistory = ref(false), history = ref([]);
const homeView = useRemember('summary', 'resolutions:home-view');
const viewMode = ref('list'), selected = ref(null), detailsOpen = ref(false);
async function switchHome(view, focus = false) { homeView.value = view; advanced.value = false; selected.value = null; detailsOpen.value = false; if (focus) { await nextTick(); document.getElementById(`repository-tab-${view}`)?.focus(); } }
const folderName = folder => folder?.path?.split('/').filter(Boolean).pop() || folder?.repository || 'Archivos';
function setView(mode) { viewMode.value = mode; try { localStorage.setItem('resolutions-view:drive', mode); } catch {} }
function openFolder(folder) { if (!folder) search.value = { ...defaults }; else search.value.folder = folder.id; selected.value = null; detailsOpen.value = false; runSearch(); }
function openYear(year, type = 'all', status = 'all') { search.value = { ...defaults, year, series: props.seriesOptions.find(series => series.code === type)?.id || '', status: type === 'unknown' ? 'untyped' : status }; runSearch(); }
async function showDetails(row) { selected.value = row; detailsOpen.value = true; await nextTick(); if (window.matchMedia('(max-width:900px)').matches) document.querySelector('.details-panel')?.scrollIntoView({ block: 'start' }); }
function reference(row) {
    const first = row.number_start || row.detected?.number_start;
    const last = row.number_start ? row.number_end : row.detected?.number_end;
    return `${row.series || row.detected?.series || 'Resolución'}${first ? ` N.º ${first}${last ? `–${last}` : ''}` : ''}`;
}
let searchVisit = null, blurTimer = null;
const editForm = useForm({ series_id: '', year: '', number_start: '', number_end: '' });
const number = value => new Intl.NumberFormat('es-PE').format(value || 0);
const size = bytes => bytes < 1024 ** 2 ? `${Math.round(bytes / 1024)} KB` : bytes < 1024 ** 3 ? `${(bytes / 1024 ** 2).toFixed(1)} MB` : `${(bytes / 1024 ** 3).toFixed(1)} GB`;
const incomplete = row => !row.year || !row.number_start || !row.series_id;
const missingData = row => [!row.series_id && 'serie', !row.number_start && 'número', !row.year && 'año'].filter(Boolean).join(', ');
const filterCount = computed(() => ['number', 'series'].filter(key => search.value[key] !== '' && search.value[key] != null).length);
const activeFilters = computed(() => [
    props.filters.q && { key: 'q', text: `Texto: ${props.filters.q}` },
    props.filters.number && { key: 'number', text: `N.º ${props.filters.number}` },
    props.filters.year && { key: 'year', text: `Año ${props.filters.year}` },
    props.filters.series && { key: 'series', text: props.seriesOptions.find(i => Number(i.id) === Number(props.filters.series))?.code || 'Serie' },
].filter(Boolean));
const previewIndex = computed(() => props.records.data.findIndex(row => row.id === preview.value?.id));
const historyKey = `resolutions-searches:${page.props.auth?.user?.id || page.props.auth?.user?.username || 'local'}`;
watch(() => props.filters, filters => search.value = { ...defaults, ...filters }, { deep: true });
watch(() => props.records.data, rows => { if (preview.value) preview.value = rows.find(row => row.id === preview.value.id) || null; if (selected.value) selected.value = rows.find(row => row.id === selected.value.id) || null; if (!selected.value) { detailsOpen.value = false; editing.value = null; } });
function remember(query) {
    if (query.trim().length < 2) return;
    history.value = [query.trim(), ...history.value.filter(q => q !== query.trim())].slice(0, 5);
    try { localStorage.setItem(historyKey, JSON.stringify(history.value)); } catch {}
}
function clearHistory() { history.value = []; try { localStorage.removeItem(historyKey); } catch {} }
function runSearch(saveQuery = false) {
    if (saveQuery) remember(search.value.q);
    showHistory.value = false; notice.value = ''; editing.value = null; selected.value = null; detailsOpen.value = false;
    searchVisit?.cancel();
    const params = Object.fromEntries(Object.entries(search.value).filter(([key, value]) => !['review', 'page'].includes(key) && value !== '' && value != null && !(key === 'status' && value === 'all') && !(key === 'sort' && value === 'recent')));
    router.get('/resoluciones', params, {
        preserveState: true, preserveScroll: true,
        onCancelToken: token => searchVisit = token,
        onStart: () => searching.value = true,
        onFinish: () => { searching.value = false; searchVisit = null; },
    });
}
function removeFilter(key) { search.value[key] = ''; runSearch(); }
function clearFilters() { search.value = { ...defaults }; runSearch(); }
function reuse(query) { search.value = { ...defaults, q: query }; runSearch(); }
function blurSearch() { blurTimer = setTimeout(() => showHistory.value = false, 160); }
function subject(row) { return row.title || row.filename.replace(/\.\s*pdf$/i, '').trim(); }
function highlight(text) {
    const tokens = (props.filters.q || '').trim().split(/\s+/).filter(q => q.length >= 2).slice(0, 8);
    if (!tokens.length) return [{ text, match: false }];
    const fold = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
    const regex = new RegExp(tokens.map(token => fold(token).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|'), 'g');
    const parts = []; let last = 0;
    for (const match of fold(text).matchAll(regex)) {
        if (match.index > last) parts.push({ text: text.slice(last, match.index), match: false });
        parts.push({ text: text.slice(match.index, match.index + match[0].length), match: true });
        last = match.index + match[0].length;
    }
    if (last < text.length) parts.push({ text: text.slice(last), match: false });
    return parts.length ? parts : [{ text, match: false }];
}
function movePreview(delta) { const row = props.records.data[previewIndex.value + delta]; if (row) preview.value = row; }
async function edit(row) {
    editing.value = editing.value === row.id ? null : row.id; editForm.clearErrors();
    Object.assign(editForm, { series_id: row.series_id || props.seriesOptions.find(series => series.code === row.detected?.series)?.id || '', year: row.year || row.detected?.year || '', number_start: row.number_start || row.detected?.number_start || '', number_end: row.number_start ? (row.number_end || '') : (row.detected?.number_end || '') });
    await nextTick(); document.getElementById(`edit-resolution-${row.id}`)?.querySelector('select')?.focus();
}
function save() { editForm.patch(`/resoluciones/${editing.value}`, { preserveScroll: true, onSuccess: () => { editing.value = null; notice.value = 'Identificación guardada.'; } }); }
function shortcut(event) {
    if (event.key === 'Escape' && !document.querySelector('dialog[open]') && !['INPUT', 'TEXTAREA', 'SELECT'].includes(event.target.tagName)) {
        selected.value = null; detailsOpen.value = false; editing.value = null; return;
    }
    if (event.key !== '/' || event.ctrlKey || event.metaKey || event.altKey || document.querySelector('dialog[open]')) return;
    if (['INPUT', 'TEXTAREA', 'SELECT'].includes(event.target.tagName) || event.target.isContentEditable) return;
    event.preventDefault(); searchInput.value?.focus();
}
function focusFirst() { resultsList.value?.querySelector('.filename-button')?.focus(); }
onMounted(() => {
    try { const savedView = localStorage.getItem('resolutions-view:drive'); if (['grid', 'list'].includes(savedView)) viewMode.value = savedView; } catch {}
    try { const stored = JSON.parse(localStorage.getItem(historyKey) || '[]'); history.value = Array.isArray(stored) ? stored.filter(q => typeof q === 'string' && q.length <= 120).slice(0, 5) : []; } catch {}
    window.addEventListener('keydown', shortcut);
});
onBeforeUnmount(() => { stopLoadingStart(); stopLoadingFinish(); stopLoadingNavigate(); clearTimeout(blurTimer); window.removeEventListener('keydown', shortcut); });
</script>

<template>
    <Head title="Resoluciones" />
    <MainLayout>
        <div class="resolution-workspace">
            <header class="drive-header">
                <div class="drive-brand"><span class="brand-folder"><FolderOpen :size="25" /></span><div><h1>Resoluciones</h1></div></div>
                <form class="drive-search" @submit.prevent="runSearch(true)">
                    <button type="submit" class="icon-button search-trigger" aria-label="Buscar resoluciones" :disabled="searching"><Loader2 v-if="searching" :size="20" class="animate-spin" /><Search v-else :size="21" /></button>
                    <label for="resolution-search" class="sr-only">Buscar en Resoluciones</label>
                    <input id="resolution-search" ref="searchInput" v-model="search.q" type="search" maxlength="120" autocomplete="off" placeholder="Buscar en Resoluciones" :aria-expanded="showHistory && history.length > 0" @focus="showHistory = true" @blur="blurSearch" @keydown.esc="showHistory = false" @keydown.down.prevent="focusFirst" />
                    <div v-if="showHistory && history.length" class="search-history"><div class="history-label">Búsquedas recientes<button type="button" @mousedown.prevent @click="clearHistory">Borrar</button></div><button v-for="query in history" :key="query" type="button" @mousedown.prevent @click="reuse(query)"><History :size="16" /><span>{{ query }}</span><ArrowUpRight :size="15" /></button></div>
                </form>
                <button v-if="access.subir" class="primary-button header-upload" @click="openResolutionUploads({ maxMb: maxUploadMb, currentYear })"><Upload :size="18" /><span>Subir resoluciones</span></button>
                <button class="icon-button help-button" :aria-expanded="help" aria-controls="resolution-help" aria-label="Ayuda de Resoluciones" @click="help = !help"><CircleHelp :size="21" /></button>
            </header>

            <section v-if="help" id="resolution-help" class="help-panel" aria-label="Ayuda de Resoluciones"><div><strong>Busque por referencia o asunto</strong><p>Escriba «125-2024», «RDR 125-2024», apellidos o palabras del nombre del PDF. Pulse / para ir al buscador.</p></div><div><strong>Archivos y numeración</strong><p>Se conservan los nombres originales. Los PDF repetidos se omiten. El control de numeración señala saltos entre el 1 y el mayor número cargado; no confirma que esas resoluciones hayan sido emitidas.</p></div></section>
            <p v-if="notice" class="notice" role="status"><Check :size="17" />{{ notice }}<button class="icon-button" aria-label="Cerrar aviso" @click="notice = ''"><X :size="16" /></button></p>

            <section class="drive-surface" :class="{ 'is-home': showDashboard }" aria-label="Repositorio de resoluciones">
                <div v-if="!showDashboard" class="drive-titlebar">
                    <div class="location-heading"><nav class="breadcrumbs" aria-label="Ubicación"><button :class="{ 'at-root': !currentFolder }" @click="openFolder(null)">{{ showDashboard ? 'Archivo institucional' : 'Inicio' }}</button><template v-if="currentFolder"><ChevronRight :size="19" /><h2 :title="currentFolder.path">{{ folderName(currentFolder) }}</h2></template></nav></div>
                </div>

                <nav v-if="showDashboard" class="repository-tabs" role="tablist" aria-label="Vistas del repositorio"><button id="repository-tab-summary" role="tab" :aria-selected="homeView === 'summary'" aria-controls="repository-summary" :tabindex="homeView === 'summary' ? 0 : -1" @click="switchHome('summary')" @keydown.right.prevent="switchHome('folders', true)"><ChartColumn :size="17" /> Resumen</button><button id="repository-tab-folders" role="tab" :aria-selected="homeView === 'folders'" aria-controls="repository-folders" :tabindex="homeView === 'folders' ? 0 : -1" @click="switchHome('folders')" @keydown.left.prevent="switchHome('summary', true)"><FolderOpen :size="17" /> Carpetas <span v-if="folders.length">{{ number(folders.length) }}</span></button></nav>
                <p v-for="key in ['q', 'number', 'year', 'series', 'folder']" v-show="page.props.errors?.[key]" :key="key" class="error-message" role="alert">{{ page.props.errors?.[key] }}</p>

                <div v-if="!showDashboard" class="drive-toolbar">
                    <div class="quick-filters">
                        <label><span class="sr-only">Filtrar por año</span><select v-model="search.year" :class="{ 'has-value': search.year }" @change="runSearch()"><option value="">Todos los años</option><option v-for="year in years" :key="year" :value="year">{{ year }}</option></select></label>
                        <label><span class="sr-only">Tipo de documentos</span><select v-model="search.status" :class="{ 'has-value': search.status !== 'all' }" @change="runSearch()"><option value="all">Todos los PDF</option><option value="grouped">PDF agrupados</option><option value="repeated">Números repetidos</option><option value="untyped">Tipo sin identificar</option><option value="review">Datos por completar ({{ number(summary.review) }})</option></select></label>
                        <button class="filter-button" :class="{ active: advanced || filterCount }" :aria-expanded="advanced" aria-controls="resolution-filters" @click="advanced = !advanced"><SlidersHorizontal :size="15" /> Más filtros<span v-if="filterCount">{{ filterCount }}</span></button>
                    </div>
                    <div class="view-switch" role="group" aria-label="Vista de archivos"><button :class="{ selected: viewMode === 'list' }" :aria-pressed="viewMode === 'list'" aria-label="Vista de lista" @click="setView('list')"><List :size="19" /></button><button :class="{ selected: viewMode === 'grid' }" :aria-pressed="viewMode === 'grid'" aria-label="Vista de cuadrícula" @click="setView('grid')"><LayoutGrid :size="18" /></button></div>
                </div>
                <form v-if="advanced" id="resolution-filters" class="advanced-filters" @submit.prevent="runSearch(true)"><label>N.º de resolución<input v-model="search.number" type="number" min="1" max="999999" placeholder="Ej. 125" /></label><label>Serie<select v-model="search.series"><option value="">Todas las series</option><option v-for="series in seriesOptions" :key="series.id" :value="series.id">{{ series.code }} — {{ series.name }}</option></select></label><button class="primary-button" :disabled="searching">Aplicar filtros</button></form>
                <div v-if="activeFilters.length" class="active-filters" aria-label="Filtros aplicados"><button v-for="filter in activeFilters" :key="filter.key" :aria-label="`Quitar filtro ${filter.text}`" @click="removeFilter(filter.key)">{{ filter.text }}<X :size="13" /></button><button class="clear-filters" @click="clearFilters">Limpiar filtros</button></div>

                <div class="explorer-layout" :class="{ 'with-details': detailsOpen && selected }">
                    <div class="explorer-content" :aria-busy="pageLoading">
                        <ResolutionSkeleton v-if="pageLoading" :variant="loadingView === 'files' && viewMode === 'grid' ? 'grid' : loadingView" />
                        <ResolutionDashboard v-if="!pageLoading && showDashboard && homeView === 'summary'" id="repository-summary" role="tabpanel" aria-labelledby="repository-tab-summary" :year-counts="yearCounts" :annual-by-series="annualBySeries" :series-options="seriesOptions" :current-year="currentYear" :total="summary.total"  :expected-year-totals="expectedYearTotals" :coverage="coverage" @year="openYear" @repeated="(year, type) => openYear(year, type, 'repeated')" />
                        <ResolutionFolders v-if="!pageLoading && showDashboard && homeView === 'folders'" id="repository-folders" role="tabpanel" aria-labelledby="repository-tab-folders" :folders="folders" :current-year="currentYear" @open="openFolder" />

                        <template v-if="!pageLoading && !showDashboard">
                        <div class="section-heading files-heading"><h2>Archivos</h2><label class="sort-control"><span class="sr-only">Ordenar archivos</span><select v-model="search.sort" @change="runSearch()"><option value="recent">Año más reciente</option><option value="oldest">Año más antiguo</option><option value="name">Nombre del archivo</option></select></label></div>
                        <div v-if="!records.data.length" class="empty-state"><FolderOpen :size="42" /><h3>{{ summary.total ? 'No hay archivos que coincidan' : 'Su archivo empieza aquí' }}</h3><p>{{ summary.total ? 'Cambie los filtros o busque con otras palabras del nombre.' : 'Suba sus resoluciones en PDF para consultarlas desde este espacio.' }}</p><button v-if="summary.total" class="secondary-button" @click="clearFilters">Ver todos los archivos</button><button v-else-if="access.subir" class="primary-button" @click="openResolutionUploads({ maxMb: maxUploadMb, currentYear })">Subir primeros PDF</button></div>
                        <div v-if="records.data.length && viewMode === 'list'" class="list-columns" aria-hidden="true"><span>Nombre</span><span>Año</span><span>Tamaño</span><span></span></div>
                        <div v-if="records.data.length" ref="resultsList" class="files" :class="`files-${viewMode}`" :aria-busy="searching">
                            <article v-for="row in records.data" :key="row.id" class="file" :class="{ selected: selected?.id === row.id }" tabindex="0" :aria-label="row.filename" @click="selected = row; editing = null" @dblclick="preview = row" @keydown.enter.self.prevent="preview = row" @keydown.space.self.prevent="selected = row">
                                <div v-if="viewMode === 'grid'" class="file-cover" aria-hidden="true"><div class="pdf-sheet"><FileText :size="39" :stroke-width="1.2" /><span>PDF</span></div><span class="cover-year">{{ row.year || 'Sin año' }}</span><FileStack v-if="row.number_end" :size="18" class="cover-group" /></div>
                                <div class="file-name"><FileText :size="20" class="pdf-icon" /><div><button class="filename-button" :title="row.filename" @click.stop="preview = row"><template v-for="(part, index) in highlight(subject(row))" :key="index"><mark v-if="part.match">{{ part.text }}</mark><template v-else>{{ part.text }}</template></template></button><p>{{ reference(row) }}<span v-if="viewMode === 'grid'"> · {{ size(row.size_bytes) }}</span><span v-else class="mobile-file-meta"> · {{ row.year || 'Sin año' }} · {{ size(row.size_bytes) }}</span></p></div></div>
                                <span v-if="viewMode === 'list'" class="file-year">{{ row.year || 'Sin año' }}</span><span v-if="viewMode === 'list'" class="file-size">{{ size(row.size_bytes) }}</span>
                                <div class="file-actions"><span v-if="incomplete(row)" class="review-indicator" :title="`Datos del nombre por completar: ${missingData(row)}.`"><span class="sr-only">Datos por completar: {{ missingData(row) }}</span></span><button class="icon-button" :aria-label="`Información: ${row.filename}`" title="Información del archivo" @click.stop="showDetails(row)"><Info :size="17" /></button></div>
                            </article>
                        </div>
                        <nav v-if="records.total" class="pagination" aria-label="Paginación"><p>{{ number(records.from) }}–{{ number(records.to) }} de {{ number(records.total) }} archivos</p><div><Link v-if="records.prev_page_url" :href="records.prev_page_url" preserve-scroll class="icon-button" aria-label="Página anterior"><ChevronLeft :size="19" /></Link><button v-else class="icon-button" disabled aria-label="Página anterior"><ChevronLeft :size="19" /></button><span>{{ records.current_page }} / {{ number(records.last_page) }}</span><Link v-if="records.next_page_url" :href="records.next_page_url" preserve-scroll class="icon-button" aria-label="Página siguiente"><ChevronRight :size="19" /></Link><button v-else class="icon-button" disabled aria-label="Página siguiente"><ChevronRight :size="19" /></button></div></nav>
                        </template>
                    </div>

                    <aside v-if="!pageLoading && detailsOpen && selected" class="details-panel" aria-label="Información del archivo"><div class="details-heading"><h2>Información</h2><button class="icon-button" aria-label="Cerrar información" @click="detailsOpen = false; editing = null"><X :size="19" /></button></div><div class="details-cover" aria-hidden="true"><FileText :size="48" :stroke-width="1.2" /><span>PDF</span></div><h3>{{ subject(selected) }}</h3><div v-if="incomplete(selected)" class="review-note"><strong>Datos por completar: {{ missingData(selected) }}</strong><p>Puede consultar el PDF y completar su identificación después.</p></div><dl><dt>Nombre original</dt><dd>{{ selected.filename }}</dd><dt>Referencia</dt><dd>{{ reference(selected) }}</dd><dt>Año</dt><dd>{{ selected.year || 'Sin identificar' }}</dd><dt>Tamaño</dt><dd>{{ size(selected.size_bytes) }}</dd><dt>Ubicación</dt><dd>{{ selected.repository }}<br />{{ selected.folder || 'Carpeta raíz' }}</dd></dl><a :href="`/resoluciones/${selected.id}/archivo?download=1`" class="secondary-button"><Download :size="16" /> Descargar</a><button v-if="access.editar" class="edit-link" @click="edit(selected)"><Pencil :size="14" />{{ editing === selected.id ? 'Cerrar edición' : 'Revisar identificación' }}</button>
                        <form v-if="access.editar && editing === selected.id" :id="`edit-resolution-${selected.id}`" class="edit-form" @submit.prevent="save"><h3>Identificación</h3><label>Serie<select v-model="editForm.series_id"><option value="">Sin confirmar</option><option v-for="series in seriesOptions" :key="series.id" :value="series.id">{{ series.code }}</option></select></label><label>Año<input v-model="editForm.year" type="number" min="1900" :max="currentYear" /></label><label>Número inicial<input v-model="editForm.number_start" type="number" min="1" max="999999" :required="!!editForm.number_end" /></label><label>Número final (si agrupa)<input v-model="editForm.number_end" type="number" min="1" max="999999" /></label><p>Confirme los datos con el PDF; deje en blanco lo que desconozca.</p><p v-for="(error, key) in editForm.errors" :key="key" class="error-message" role="alert">{{ error }}</p><button class="primary-button" :disabled="editForm.processing">{{ editForm.processing ? 'Guardando…' : 'Guardar' }}</button></form>
                    </aside>
                </div>
            </section>
        </div>
        <ResolutionPreview :record="preview" :position="previewIndex" :total="records.data.length" @previous="movePreview(-1)" @next="movePreview(1)" @close="preview = null" />
    </MainLayout>
</template>
